ControlPropertyState.AutoRuleBindingString:
If(
    IsBlank(drp_EstadoPermiso_EP.Selected),
    UpdateContext({Aviso: true, textoAviso: "Debe seleccionar el estado"}),
    drp_EstadoPermiso_EP.Selected.Nombre = "Aprobado" && !chk_Remunerado_EP.Value && !chk_NoRemunerado_EP.Value,
    Notify(
        "Debe seleccionar el tipo de remuneracion",
        NotificationType.Error
    ),
    drp_EstadoPermiso_EP.Selected.Nombre = "Rechazado" && IsBlank(txt_MotivoRechazo_EP.Text),
    Notify(
        "Debe indicar el motivo del rechazo",
        NotificationType.Error
    ),
    UpdateContext({ConVisible: true});

);
